#!/bin/sh
# Generated by subscriber-engine for session 11111111-2222-3333-4444-555555555555. Runs the agent without a window or a person and records how it ended.
# Only validated values are substituted into this file; the repository is a quoted literal.
session='C:\appmod data\sessions\11111111-2222-3333-4444-555555555555'
repository='C:\work\r&d 100% ^'\''x (1) é\shop'
code=1
write_exit() {
    head=$(git -C "$repository" rev-parse HEAD 2>/dev/null)
    ended=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    if [ -n "$head" ]; then head_json="\"$head\""; else head_json=null; fi
    printf '{"exitCode":%s,"endedAt":"%s","headEnd":%s}\n' "$code" "$ended" "$head_json" > "$session/exit.json.tmp" \
        && mv -f "$session/exit.json.tmp" "$session/exit.json"
}
trap write_exit EXIT
trap 'code=130; exit 130' INT
trap 'code=143; exit 143' TERM
cd "$repository" || exit 1
copilot --agent security-fixer --session-id 11111111-2222-3333-4444-555555555555 --name 'appmod fix 11111111' --allow-tool 'shell(git:*)' --allow-tool 'write(C:/work/**)' --allow-tool 'shell(Test-Path)' --deny-tool 'shell(curl:*)' --deny-tool 'shell(git push:*)' --no-ask-user --add-dir "$session" --log-dir "$session/logs" --share "$session/transcript.md" -p "Read and follow $session/prompt.md"
code=$?
exit $code
